package com.canteenpro.service;
import com.canteenpro.model.Food;import org.springframework.stereotype.Service;import java.util.*;import java.util.concurrent.atomic.AtomicLong;
@Service public class FoodService {private final Map<Long,Food> foods=new LinkedHashMap<>();private final AtomicLong seq=new AtomicLong(1); public List<Food> all(){return new ArrayList<>(foods.values());}public Food get(Long id){Food f=foods.get(id);if(f==null)throw new RuntimeException("Food not found: "+id);return f;}public Food create(Food f){f.setId(seq.getAndIncrement());foods.put(f.getId(),f);return f;}public Food update(Long id,Food f){Food old=get(id);f.setId(id);foods.put(id,f);return f;}public void delete(Long id){get(id);foods.remove(id);}public List<Food> search(String q){return foods.values().stream().filter(f->f.getName()!=null&&f.getName().toLowerCase().contains(q.toLowerCase())).toList();}public List<Food> category(String c){return foods.values().stream().filter(f->c.equalsIgnoreCase(f.getCategory())).toList();}public Food stock(Long id,int qty){Food f=get(id);f.setStock(qty);f.setAvailable(qty>0);return f;}public void reduceStock(Long id,int qty){Food f=get(id);if(qty>f.getStock())throw new RuntimeException("Insufficient stock for "+f.getName());f.setStock(f.getStock()-qty);f.setAvailable(f.getStock()>0);}}